pub fn decode(data: &[u8]) -> Result<OpenResult, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0, limit: DEPTH_LIMIT };
    r.skip_ws();
    let v = decode_open_result(&mut r)?;
    r.skip_ws();
    if r.pos < r.buf.len() {
        return r.refuse("trailing_bytes");
    }
    Ok(v)
}

fn service_check_entry(_v: &Entry) -> Result<(), Refusal> {
    Ok(())
}

fn service_check_name(_v: &Name) -> Result<(), Refusal> {
    Ok(())
}

fn service_check_manifest(v: &Manifest) -> Result<(), Refusal> {
    for value in &v.entries {
        service_check_entry(value)?;
    }
    for value in &v.names {
        service_check_name(value)?;
    }
    Ok(())
}

