/// Common generated framing boundary; implementation owns waiting and identity.
pub use abstraction_frame::FrameTransport;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ServiceError {
    pub code: String,
    pub message: String,
}

#[derive(Debug)]
pub enum CallError<E> {
    /// Transport failure does not establish whether the receiver accepted work.
    Transport(E),
    Refusal(Refusal),
    Dispatch(&'static str),
    Service(ServiceError),
}

fn service_decode<T>(data: &[u8], decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<T, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0, limit: DEPTH_LIMIT };
    r.skip_ws();
    let value = decode(&mut r)?;
    r.skip_ws();
    if r.pos != data.len() {
        return r.refuse("trailing_bytes");
    }
    Ok(value)
}

fn service_encode<T>(value: &T, check: fn(&T) -> Result<(), Refusal>, encode: fn(&mut Vec<u8>, &T, i32), decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<Vec<u8>, Refusal> {
    check(value)?;
    let mut data = Vec::new();
    encode(&mut data, value, 0);
    service_decode(&data, decode)?;
    Ok(data)
}

/// Read-only bounded access through configured native Store+Local adapters.
/// Naming lookup is unverified; unsupported providers refuse. Writes use the
/// separate content-writer profile. Callbacks are trusted provider code
/// required to honor bounded execution/context.
pub trait ContentReader {
    type Error;
    /// Canonical sha256: plus 64 lowercase hexadecimal digits. Explicit content
    /// policy required; same-account identity alone grants no content
    /// permission. At most 32 resources globally and 8 per scope; 30 seconds
    /// idle expires.
    fn open(&self, digest: String) -> Result<OpenResult, Self::Error>;
    /// offset>=0; max_bytes is 1..65536. Authority rechecked before bytes.
    /// Unknown/expired/closed/restarted resources give gap; another scope's
    /// known resource gives forbidden.
    fn read(&self, handle: String, offset: i64, max_bytes: i64) -> Result<ReadResult, Self::Error>;
    /// Release own scoped resource even after content authorization revocation.
    /// Provider shutdown closes all owned resources.
    fn close(&self, handle: String) -> Result<CloseResult, Self::Error>;
}

