/// Bounded authorized writes through configured native Store+Local+Writable
/// adapters. Uploads idle for 30 seconds expire and are discarded. Committed
/// request records are retained for 10 minutes within one provider lifetime.
/// Provider shutdown discards staged uploads.
pub trait ContentWriter {
    type Error;
    /// request is a caller-retained identity of 16..128 characters from A-Z a-z
    /// 0-9 _ -, scoped to the receiving account/program. digest is canonical
    /// sha256; size is the declared total, 0..limit. Write authorization
    /// precedes every lookup and provider effect. The same request with the
    /// same digest and size returns its live upload or committed result;
    /// different digest or size is conflict. present reports an existing naming
    /// match. busy reports another live upload of the same digest. At most 16
    /// uploads globally, 4 per scope and 256 request records.
    fn begin(&self, request: String, digest: String, size: i64) -> Result<BeginResult, Self::Error>;
    /// data is 1..65536 bytes at offset equal to received. Authority rechecked
    /// before bytes are staged. A different offset stages nothing and returns
    /// out_of_order with received. Bytes beyond the declared size stage nothing
    /// and return too_large. Unknown/expired/aborted/restarted uploads give
    /// gap; another scope's upload gives forbidden.
    fn append(&self, handle: String, offset: i64, data: Vec<u8>) -> Result<AppendResult, Self::Error>;
    /// Authority rechecked before visibility. Requires received equal to size
    /// and the staged bytes to hash to digest; mismatch discards the upload.
    /// Visibility changes in one provider commit step; readers observe no
    /// partial content.
    fn commit(&self, handle: String) -> Result<CommitResult, Self::Error>;
    /// Discard own staged upload and its request record, including after write
    /// authorization revocation.
    fn abort(&self, handle: String) -> Result<AbortResult, Self::Error>;
}

