/// Declared holds of the bound program. Gated by
/// abstraction.storage/holds.manage, whose contract default permits the bound
/// program on resource self and nothing else. Holds are retained until
/// released, expired, or the program is removed under the uninstall policy;
/// released and expired holds read unknown after audit_retention_ms, readable
/// on an inventory page.
pub trait Holds {
    type Error;
    /// request is caller-retained, 16..128 characters from A-Z a-z 0-9 _ -,
    /// scoped to the receiving account and program; the same request with the
    /// same arguments returns the existing hold, different arguments conflict.
    /// Only declared holds are created here; the holder is the bound peer.
    /// lease_ms is 1..2592000000 for lease and zero otherwise. At most 4096
    /// holds per program; exhausted otherwise.
    fn hold(&self, request: String, target: String, purpose: String, lifetime: Lifetime, lease_ms: i64) -> Result<HoldResult, Self::Error>;
    /// Release an own declared hold. Another program's hold, a released hold
    /// past retention and an unknown id are unknown.
    fn release(&self, hold: String) -> Result<ReleaseResult, Self::Error>;
    /// Extend an own lease by lease_ms from the service's time. An expired
    /// lease is expired and is not revived.
    fn renew(&self, hold: String, lease_ms: i64) -> Result<RenewResult, Self::Error>;
}

